INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.105.2',
  '2026-09-30',
  'Пульт ТВ: у отправки фильмов появился выбор дорожек и размера картинки',
  E'В скрипте отправки на приставку раньше можно было взять либо одну звуковую дорожку, либо все. Теперь их можно перечислить: «--audio 0,11» возьмёт дубляж и оригинал (играть приставка всё равно будет первую).\n\nИ появилась возможность уменьшить картинку или качество: «--scale 720p», «--scale 1280x720», «--scale 70%» и «--crf 22». Оценка времени и размера в плане честно пересчитывается — видно заранее, во что обойдётся.\n\nПо делу: уменьшать разрешение ради места обычно не стоит — у приставки экран 1080p, а лишнее у домашних раздач не в разрешении, а в битрейте. «--crf 21» без уменьшения картинки превращает 13–17 Мбит/с ремукса примерно в 3,5 Мбит/с.',
  E'send-series.py: --audio принимает список («0,11») или «all» (parse_audio), ffmpeg получает по -map 0:a:N на дорожку; plan_file берёт из info[audio] все выбранные и копирует звук, только если ВСЕ они уже стерео AAC/MP3.\n\n--scale («720p» | «1280x720» | «70%») и --crf (18…28) — parse_scale отдаёт фильтр ffmpeg, подпись для плана и коэффициент уменьшения площади кадра. Любой из ключей ставит vcopy=False: поменять разрешение или качество, не трогая видео, нельзя. Масштаб не растягивает мелкое: min(W,iw) и force_divisible_by=2.\n\nОценка времени переписана по замерам на i7-11370H (x264 veryfast): раскодирование исходника и сжатие результата считаются отдельно — duration × 24 × (src_MP × 0,0044 + dst_MP × 0,0028). Отсюда 1080p→1080p вчетверо быстрее реального времени, 1080p→720p лишь немногим быстрее (раскодировать надо то же самое), 720×304 — в тридцать раз. Размер на выходе — 3,5 Мбит/с на 1080p при crf 21, дальше по площади кадра; раньше время считалось как duration/20, а передача — по размеру ИСХОДНИКА, что для перекодирования врало втрое.\n\nЗамеры на «Гарри Поттер и Дары смерти» (h264 1080p, 13,5 Мбит/с): crf 21 — 3,0 Мбит/с и 3,7× реального времени; crf 23 — 1,7 Мбит/с; 720p crf 21 — 2,0 Мбит/с и 4,4×. Экшен-сцена «Кубка огня» при crf 21 — 3,3 Мбит/с.'
);
-- +goose StatementEnd

